export const meta = {
  name: 'skill-forge-round',
  description: '跑一轮 skill 评测:答题 fan-out → Layer-1 → 判卷 fan-out(答题/判卷由主循环预生成的 plan 驱动)',
  phases: [
    { title: '答题', detail: '每 case × N run,受限 answerer agent' },
    { title: '判卷', detail: '每份生成产物一个 judge agent,pipeline 无 barrier' },
  ],
}
// args 契约(主循环在跑本 workflow 前准备好):
// {
//   domainDir: "domains/<name>", roundDir: ".../rounds/round-05",
//   skillPath, judgeCorePath, judgeDomainPath, rulingsPath,   // rulingsPath 可为 null
//   tasks: [{ case: "gt-xxx", run: 1, questionPath, gtPath, outSql, outJudgment }, ...]
// }
// 前置(主循环负责,不在本脚本内):lint_skill.py 必须 pass;round-meta.json 已落盘。
// Layer-1 由主循环在本 workflow 结束后跑(确定性脚本,不值得占 agent)。
// 判卷输入里的 layer1 行:answer 阶段结束后无法拿到,故判卷 prompt 指示 judge 自行 Read
// roundDir/layer1.jsonl 中对应行;若文件不存在按 n/a 处理。

const A = args
if (!A || !Array.isArray(A.tasks) || !A.tasks.length) throw new Error('args.tasks 为空')

const rulingsLine = A.rulingsPath ? `3. domain 裁定: ${A.rulingsPath}` : '3. domain 裁定: (本 domain 无,跳过)'

const results = await pipeline(
  A.tasks,
  // 阶段 1:答题(受限 agent,只给 skill + 考题)
  t => agent(
    [
      `按你的 agent 规程答题。`,
      `SKILL.md: ${A.skillPath}`,
      `考题: ${t.questionPath}`,
      `产物写入: ${t.outSql}`,
    ].join('\n'),
    { label: `answer:${t.case}#${t.run}`, phase: '答题', agentType: 'skill-answerer' }
  ),
  // 阶段 2:判卷(单 case 答完即判,不等全体)
  (_ans, t) => agent(
    [
      `按你的 agent 规程判卷。材料:`,
      `1. 核心规程: ${A.judgeCorePath}`,
      `2. 领域段: ${A.judgeDomainPath}`,
      rulingsLine,
      `4. Ground Truth: ${t.gtPath}`,
      `5. 生成产物: ${t.outSql}`,
      `6. Layer-1: 读 ${A.roundDir}/layer1.jsonl 中 file=="${t.outSql.split('/').pop()}" 的行;文件或行不存在则按 n/a。`,
      `判卷 JSON 写入: ${t.outJudgment}(case="${t.case}", run=${t.run})`,
    ].join('\n'),
    { label: `judge:${t.case}#${t.run}`, phase: '判卷', agentType: 'skill-judge' }
  )
)

const done = results.filter(Boolean).length
log(`完成 ${done}/${A.tasks.length}(失败项需主循环补跑)`)
return { total: A.tasks.length, done, failed: A.tasks.length - done }
